import{_ as l,o as t,c as i,a5 as a}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"写作课作业-100","description":"","frontmatter":{"date":"2020-11-03T00:04:01","title":"写作课作业-100","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/100.md","filePath":"posts/homework/100.md"}'),o={name:"posts/homework/100.md"};function r(s,e,p,n,_,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《一年顶十年》之《读书 如何将读过的书转化为生产力？》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>坚持读书，等于坚持锻炼并升级自己的大脑。</li><li>读书这个事儿，本就应该是终身成长者的标配。</li><li>多读，猛读。越早突破新手期，你就越容易尝到读书的甜头，越容易建立良好的阅读习惯。</li><li>用，才是最好的读。重复读，多读几遍；读的过程中思考怎么去用，还要真的去用，且努力做出成绩；分享给更多人。</li><li>一开始忍受阅读速度慢，随着阅读量的不断增加，掌握的词汇越来越多，你的只是储备越来越丰富，你的信息处理能力越来越强，你的阅读速度自然会越来越快。</li><li><strong>碎片化阅读，也是阅读啊。“强迫”自己继续读，不管状态如何，读就是了。</strong></li><li>写“践行清单”比读书笔记更有有效。读书之后根据自己的实际情况回答两个问题：有哪些内容时我用得上的？针对每一条内容，我该怎么做？把这两个问题的答案写出来，你得到的就是一本书的践行清单。</li><li>必读的书有：历史类书籍，任务传记，升级商业思维的书，励志书。</li><li>挑书，是需要大量练习的。大量翻书，以人找书，以书找书。</li><li><strong>读书三板斧：重复读，盯作者，勤分享。</strong></li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>当看到「将读过的书转化为生产力」的时候，我第一个想到是，自己读的书都记不住，还怎么转化成生产力呢？当读到「用，才是最好的读」时，是恍然大悟。自己学习编程的时候不就这样的吗，一遍读书，一遍工作马上就要用了，不就是边用边学么？</p><p>不管自己状态如何，读就是了。就如定投，不管价格如何，买就是了。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',13)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
